practice.solution:
import math
def self_attend(X):
    d = len(X[0])
    out = []
    for q in X:
        sc = []
        for k in X:
            s = 0.0
            for a, b in zip(q, k):
                s += a * b
            sc.append(s / math.sqrt(d))
        m = max(sc)
        es = [math.exp(t - m) for t in sc]
        tot = sum(es)
        o = [0.0] * d
        for e, v in zip(es, X):
            for j in range(d):
                o[j] += e / tot * v[j]
        out.append([round(t, 6) for t in o])
    return out

