practice.solution:
def greedy_decode(T, start, end, max_len):
    seq = [start]
    while len(seq) < max_len:
        probs = T[seq[-1]]
        best = 0
        for i in range(1, len(probs)):
            if probs[i] > probs[best]:
                best = i
        seq.append(best)
        if best == end:
            break
    return seq

